import{_ as a,o,c as t,a2 as r}from"./chunks/framework.CiKk3sJz.js";const m=JSON.parse('{"title":"漫画 · 第 16 话 Web Storage：刷新不丢的键值仓库","description":"","frontmatter":{},"headers":[],"relativePath":"comics/html/EP.16-web-storage.md","filePath":"comics/html/EP.16-web-storage.md","lastUpdated":1792579602000}'),l={name:"comics/html/EP.16-web-storage.md"};function s(i,e,n,h,c,d){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="漫画-·-第-16-话-web-storage-刷新不丢的键值仓库" tabindex="-1">漫画 · 第 16 话 Web Storage：刷新不丢的键值仓库 <a class="header-anchor" href="#漫画-·-第-16-话-web-storage-刷新不丢的键值仓库" aria-label="Permalink to &quot;漫画 · 第 16 话 Web Storage：刷新不丢的键值仓库&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/html/05-web-storage">docs/html/05-web-storage.md</a> ｜ 原画：<a href="./EP.16-web-storage.svg">EP.16-web-storage.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，把表格列配置塞进 Cookie，结果单条 4KB 存不下，还发现连请求一张 logo.png 都背着这串数据，读写时还得自己拼字符串算过期。</li><li><strong>标签君</strong>：HTML5 结构师，本话主角。拿出 localStorage / sessionStorage 两个 API 完全一致、生命周期完全不同的仓库，并演示 storage 事件与生产级封装。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>Web Storage 是浏览器端的同源键值对存储：不随 HTTP 请求发送、容量 5~10MB、原生 get/set 同步 API。它取代了&quot;什么都往 Cookie 塞&quot;的旧模式——需要服务器认识的凭证留 Cookie，只想让浏览器记住的前端状态全部搬进 Storage。唯一的门槛是：值只能是字符串，以及各种写入失败的边界必须兜住。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>Cookie 三个硬伤：每个同源 HTTP 请求自动携带（图片、接口都背着，白白增大请求头）；单条约 4KB、每域约 50 条；<code>document.cookie</code> 只是字符串，读写要自己解析拼接。表格列配置、一页缓存数据根本塞不下。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>两个仓库 API 相同（都实现 Storage 接口）、按同源隔离：<code>localStorage</code> 持久化，关浏览器重启电脑都在，适合主题、语言、长期缓存；<code>sessionStorage</code> 绑定当前标签页会话，刷新保留、关标签页销毁，适合表单草稿、多步向导。storage 事件是零依赖广播：任一标签页改了 localStorage，浏览器向<strong>同源的其他所有标签页</strong>派发事件（key/oldValue/newValue/url），写入页自己收不到——A 页加购物车、B 页角标实时更新就靠它。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>值只能存字符串：裸存对象读回来是 <code>&quot;[object Object]&quot;</code>，必须 <code>JSON.stringify/parse</code> 成对使用；注意 undefined 序列化会消失、循环引用抛 TypeError、读不到返回 null。生产封装做四件事：命名空间前缀防 key 冲突；包一层 <code>{v, e}</code> 实现 TTL 过期；探针检测存储可用性，隐私模式/被禁用时降级内存 Map；所有 setItem try/catch，配额满（QuotaExceededError）不中断业务。敏感信息（密码、长期 token）绝不入 Storage——XSS 下完全透明可读，HttpOnly Cookie 才是它们的位置。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>localStorage 持久、sessionStorage 随标签页，同源隔离、不随请求发送；只存字符串，对象必须 stringify/parse 成对。</li><li>storage 事件只广播给同源其他标签页；配额满与隐私模式会抛错，setItem 一律 try/catch + 内存降级。</li><li>key 加命名空间、TTL 自己实现、clear() 是核弹别乱按；敏感凭证交给 HttpOnly Cookie。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：在标签页 A 里监听了 storage 事件，然后自己在 A 里 <code>setItem(&#39;theme&#39;,&#39;dark&#39;)</code>，回调为什么不触发？怎么让 A 页 UI 也更新？</p><p><strong>答</strong>：这是规范的刻意设计：storage 事件只派发给<strong>同源的其他</strong>窗口/标签页，执行修改的当前页面不收到，避免&quot;自己写自己收&quot;的循环反馈。本页 UI 必须在写入处同步更新——标准模式是把&quot;改数据 + 改本页 UI&quot;放在同一个操作函数里，其他标签页靠 storage 事件被动同步；不要试图靠本页 storage 事件驱动自己的渲染。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>存储基础：API 全操作 + 生命周期对比 + 容量压测 + 序列化陷阱：<a href="./../../examples/html/05-web-storage/index-01-storage-basics.html">examples/html/05-web-storage/index-01-storage-basics.html</a></li><li>storage 事件：双标签页主题/购物车实时同步：<a href="./../../examples/html/05-web-storage/index-02-storage-event-sync.html">index-02-storage-event-sync.html</a></li><li>生产级封装：命名空间 + TTL 过期 + 内存降级 + 安全 JSON：<a href="./../../examples/html/05-web-storage/index-03-storage-wrapper.html">index-03-storage-wrapper.html</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 17 话《Web Workers》——JS 也能多线程：把冻住页面的重计算丢进后台，消息一来一回，动画照常丝滑。</p>',22)])])}const u=a(l,[["render",s]]);export{m as __pageData,u as default};
